pending_checks.command:
sh -c 'set -eu
TAG=v0.0.1-rc.8
VER="${TAG#v}"
BASE="${B1_RELEASE_BASE:-https://github.com/ai-agent-assembly/agent-assembly/releases/download}/$TAG"
D="$(mktemp -d)"
trap '"'"'rm -rf "$D"'"'"' EXIT
sha() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d'"'"' '"'"' -f1; else shasum -a 256 "$1" | cut -d'"'"' '"'"' -f1; fi; }
need_sha() { [ "$(sha "$1")" = "$2" ] || { echo "digest mismatch for $1 (candidate expects $2)" >&2; exit 1; }; }
need_ver() { case "$1" in *"$VER"*) ;; *) echo "version output '"'"'$1'"'"' lacks $VER" >&2; exit 1 ;; esac; }
command -v brew >/dev/null 2>&1 || { echo "brew not found" >&2; exit 1; }
brew upgrade ai-agent-assembly/tap/aasm || brew install ai-agent-assembly/tap/aasm
P="$(brew --prefix)/bin"
[ -x "$P/aa-gateway" ] || { echo "aa-gateway not installed by the formula" >&2; exit 1; }
need_ver "$("$P/aa-gateway" --version)"
need_sha "$P/aa-gateway" a0a25523655c1629d0da940cf0417453c8ad75e9be3ed2d48e0f26e55b7d1619
'

sh -c 'set -eu
TAG=v0.0.1-rc.8
VER="${TAG#v}"
BASE="${B1_RELEASE_BASE:-https://github.com/ai-agent-assembly/agent-assembly/releases/download}/$TAG"
D="$(mktemp -d)"
trap '"'"'rm -rf "$D"'"'"' EXIT
sha() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d'"'"' '"'"' -f1; else shasum -a 256 "$1" | cut -d'"'"' '"'"' -f1; fi; }
need_sha() { [ "$(sha "$1")" = "$2" ] || { echo "digest mismatch for $1 (candidate expects $2)" >&2; exit 1; }; }
need_ver() { case "$1" in *"$VER"*) ;; *) echo "version output '"'"'$1'"'"' lacks $VER" >&2; exit 1 ;; esac; }
command -v docker >/dev/null 2>&1 || { echo "docker not found" >&2; exit 1; }
docker manifest inspect "ghcr.io/ai-agent-assembly/aa-runtime:$TAG" > "$D/m.json"
python3 -I -c '"'"'import json,sys; m=json.load(open(sys.argv[1])); p={(x["platform"]["os"],x["platform"]["architecture"]) for x in m.get("manifests",[])}; sys.exit(0 if {("linux","amd64"),("linux","arm64")}<=p else 1)'"'"' "$D/m.json"
'
